"const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    headless: "new",
    args: ['--allow-file-access-from-files', '--disable-web-security', '--no-sandbox']
  });
  const page = await browser.newPage();

  page.on('console', msg => console.log('BROWSER CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'load', timeout: 15000 });
  await new Promise(r => setTimeout(r, 1000));

  // Switch to Meal Planner
  console.log("Switching tab to diettrades...");
  await page.evaluate(() => switchTab('diettrades'));
  await new Promise(r => setTimeout(r, 500));

  // Fill in the meal text
  const mealText = "6oz breaded chicken, 3oz lettuce and baby tomato salad, 3 oz cottage cheese, 12 oz water";
  console.log("Entering meal text:", mealText);
  await page.evaluate((txt) => {
    const el = document.getElementById('txtMealBuilderInput');
    el.value = txt;
  }, mealText);

  // Click ESTIMATE WITH GEMINI
  console.log("Clicking ESTIMATE WITH GEMINI...");
  await page.evaluate(() => {
    analyzeMealWithGemini();
  });
  await new Promise(r => setTimeout(r, 3000));

  // Check what title is displayed
  const title = await page.evaluate(() => document.getElementById('lblGeminiMealTitle')?.textContent);
  console.log("Displayed Meal Title:", title);

  const netCarbs = await page.evaluate(() => document.getElementById('chipNetCarbs')?.textContent);
  console.log("Displayed Net Carbs:", netCarbs);

  const cals = await page.evaluate(() => document.getElementById('chipCalories')?.textContent);
  console.log("Displayed Calories:", cals);

  await browser.close();
  process.exit(0);
})();
"

