"const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    args: ['--no-sandbox', '--allow-file-access-from-files']
  });
  const page = await browser.newPage();
  const errors = [];
  const logs = [];
  page.on('pageerror', err => errors.push(err.toString()));
  page.on('console', msg => {
    logs.push(`[${msg.type()}] ${msg.text()}`);
    if (msg.type() === 'error') errors.push(msg.text());
  });

  await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 2000));

  console.log('=== Console Errors ===');
  console.log(errors);

  console.log('=== Recent Logs ===');
  console.log(logs.slice(-20));

  const pageDetails = await page.evaluate(() => {
    const main = document.querySelector('main');
    const pages = Array.from(document.querySelectorAll('main > div, .tab-pane, [id^="page"]'));
    return {
      mainExists: !!main,
      mainInnerHTML: main ? main.innerHTML.substring(0, 300) : null,
      pageCount: pages.length,
      pages: pages.map(p => ({
        id: p.id,
        className: p.className,
        styleDisplay: p.style.display,
        computedDisplay: window.getComputedStyle(p).display
      }))
    };
  });

  console.log('=== Page Details ===');
  console.log(JSON.stringify(pageDetails, null, 2));

  await browser.close();
})();
"

