def parse_pb(data, pos, end, depth=0):
    out = []
    while pos < end:
        start_pos = pos
        b = data[pos]; pos += 1
        key = b & 0x7f; shift = 7
        while b & 0x80 and pos < end:
            b = data[pos]; pos += 1
            key |= (b & 0x7f) << shift; shift += 7
        fn = key >> 3; wt = key & 7
        if fn == 0 or fn > 80: break
        if wt == 0:
            b = data[pos]; pos += 1
            val = b & 0x7f; shift = 7
            while b & 0x80 and pos < end:
                b = data[pos]; pos += 1
                val |= (b & 0x7f) << shift; shift += 7
            out.append((fn, val))
        elif wt == 2:
            b = data[pos]; pos += 1
            ln = b & 0x7f; shift = 7
            while b & 0x80 and pos < end:
                b = data[pos]; pos += 1
                ln |= (b & 0x7f) << shift; shift += 7
            if pos + ln > end: break
            chunk = data[pos:pos+ln]; pos += ln
            if depth < 2 and 2 <= ln <= 200:
                sub = parse_pb(chunk, 0, ln, depth+1)
                if sub: out.append((fn, sub))
                else: out.append((fn, chunk.hex()))
            else:
                out.append((fn, f'bytes({ln})'))
        else:
            break
    return out

for name in ['C006.bin', 'C164.bin', 'C176.bin']:
    d = open(os.path.join('stock_dials', 'shape4_240x280', name), 'rb').read()
    # find 0x0a start around 0x20-0x30
    idx = d.find(b'\x0a', 0x20, 0x30)
    print(f'=== {name} proto@0x{idx:x} pre={d[0x20:idx].hex()} ===')
    pb = parse_pb(d, idx, min(len(d), idx+0x500))
    for item in pb[:20]:
        print(' ', item)
